import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# --- Custom CUDA kernel for element-wise addition (reused) ---
elementwise_add_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float()>, size);

    return out;
}
"""

elementwise_add_cpp_source = "torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b);"
elementwise_add = load_inline(
    name="elementwise_add",
    cpp_sources=elementwise_add_cpp_source,
    cuda_sources=elementwise_add_source,
    functions=["elementwise_add_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

# --- Custom CUDA kernel for cumulative sum (prefix sum) along a flattened dimension ---
cumsum_kernel_source = """
__global__ void cumsum_kernel(const float* input, float* output, int total_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elements) {
        float sum = 0.0f;
        for (int j = 0; j <= idx; ++j) {
            sum += input[j];
        }
        output[idx] = sum;
    }
}
"""

cumsum_cpp_source = (
    "torch::Tensor cumsum_cuda(torch::Tensor x, int dim) {\n"
    "    auto size = x.numel();\n"
    "    auto out = torch::zeros_like(x);\n\n"
    "    const int block_size = 256;\n"
    "    const int num_blocks = (size + block_size - 1) / block_size;\n\n"
    "    cumsum_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), out.data_ptr<float()>, size);\n\n"
    "    return out;\n"
    "}"
)

cumsum_cuda = load_inline(
    name="cumsum_cuda",
    cpp_sources=cumsum_cpp_source,
    cuda_sources=cumsum_kernel_source,
    functions=["cumsum_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

# --- Optimized model ---
class ModelNew(nn.Module):
    def __init__(self, dim: int = 1) -> None:
        super().__init__()
        self.dim = dim
        self.elementwise_add = elementwise_add
        self.cumsum_cuda = cumsum_cuda

    def forward(self, x):
        return self.cumsum_cuda(x, dim=self.dim)
